update public.lessons l set enhancements = $ench${"industryStory":"A team hit an intermittent failure and the assistant confidently diagnosed a timing race, suggesting a fixed wait. They added it; the flakiness moved but did not go away. Only when someone opened the trace did the real cause appear — a locator matching two elements — which no amount of waiting would fix. They removed the wait, tightened the locator, and the flakiness vanished. The lesson they drew was not \"the AI is useless\" but \"the AI gives you a lead and the trace gives you the truth\"; from then on every AI failure diagnosis was checked against a trace before anyone changed code.","badGood":{"label":"acting on a plausible explanation vs verifying it","bad":"~~~ts\n// AI said \"it's a race, add a wait\" — symptom patched, cause unknown.\nawait page.getByRole('button', { name: 'Save' }).click();\nawait page.waitForTimeout(1000); // guess dressed up as a fix\nawait expect(page.getByText('Saved')).toBeVisible(); // still ambiguous\n~~~","good":"~~~ts\n// Trace showed strict-mode ambiguity, not a race. Fix the real cause.\nawait page.getByRole('button', { name: 'Save' }).click();\nawait expect(page.getByRole('status')).toHaveText('Saved'); // one element, web-first wait\n~~~"}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"badGood":{"label":"green-but-wrong vs a test that proves the outcome","bad":"~~~ts\n// Named for saving a profile, but asserts only that a button was clickable.\ntest('profile changes are saved', async ({ page }) => {\n  await page.goto('/profile');\n  await page.getByLabel('Display name').fill('Ada Lovelace');\n  await page.getByRole('button', { name: 'Save' }).click();\n  await expect(page.getByRole('button', { name: 'Save' })).toBeVisible(); // green, proves nothing\n});\n~~~","good":"~~~ts\n// Asserts the change actually persisted — the outcome the name promises.\ntest('profile changes are saved and persist after reload', async ({ page }) => {\n  await page.goto('/profile');\n  await page.getByLabel('Display name').fill('Ada Lovelace');\n  await page.getByRole('button', { name: 'Save' }).click();\n  await expect(page.getByRole('status')).toHaveText('Profile saved');\n\n  await page.reload(); // prove it persisted, not just that a toast appeared\n  await expect(page.getByLabel('Display name')).toHaveValue('Ada Lovelace');\n});\n~~~"},"davidTip":"Keep a personal checklist for reviewing generated tests and run every one through it: does every API call exist, does every selector resolve to the intended element, and would each assertion fail if the feature broke? The discipline of a literal checklist matters more with AI output than with your own, because AI code arrives looking finished and its confidence is uniform whether it is right or wrong.","visualAid":{"type":"comparison","title":"Four failure modes of AI-generated tests and how to catch each","headers":["Failure mode","What it looks like","How you catch it"],"rows":[["Hallucinated API","A method or option Playwright never had","Type-check and run; verify against the docs"],["Invented selector","A #id or data-testid not in your app","Confirm it resolves to the intended element"],["Weak assertion","Checks a URL or visibility, not the outcome","Ask: would it fail if the feature broke?"],["Asserts nothing","A flow with no meaningful check","Break the feature; see if it stays green"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 5;

update public.lessons l set enhancements = $ench${"industryStory":"A team debugging a payment integration pasted a failing request, complete with a live gateway key, into an external assistant to get quick help. The fix worked and nobody thought more of it — until a routine security review flagged the key as potentially exposed and it had to be rotated across every service that used it, an afternoon of scramble that a one-line synthetic placeholder would have avoided entirely. The team adopted two rules the same week: secrets never leave configuration, and any secret that touches an external tool is rotated on sight. The help the AI gave was real; so was the avoidable risk, and the difference was entirely in what was pasted.","davidTip":"Build a tiny \"sanitise before you paste\" reflex: before any snippet goes into an external tool, scan it for a key, a real email, a real card, a customer name, or anything proprietary, and swap each for a synthetic equivalent. It takes seconds and it becomes automatic. The engineers who never leak data are not the cautious ones who agonise each time — they are the ones for whom sanitising is muscle memory.","visualAid":{"type":"comparison","title":"What to share with an external AI tool — and what never to","headers":["Category","Never paste the real thing","Safe stand-in to share instead"],"rows":[["Secrets","API keys, tokens, passwords","process.env references; described, not shown"],["Personal data","Real names, emails, cards","Synthetic-but-faithful fake values"],["Proprietary code","Whole confidential modules","The minimal non-sensitive slice"],["The problem shape","—","Structure, error type, behaviour — always fine"]]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'modern-test-automation-bootcamp'
  and m.module_number = 14 and l.lesson_number = 6;

update public.lessons l set enhancements = $ench${"davidTip":"Print your AI-use rules and keep them where you will see them, because the moment you need them is the moment you are least inclined to follow them — the end of a long day with a green generated draft and a deadline. A rule you decided calmly in advance is far easier to keep than a judgement you have to make under pressure. That is the entire reason to write them down rather than \"just remember\".","visualAid":{"type":"flow","title":"The plan → generate → review → verify loop","steps":[{"label":"Plan (human)","detail":"Decide what the test must prove and the risk. The AI cannot."},{"label":"Generate (AI)","detail":"Draft fast from your plan and real context."},{"label":"Review (human)","detail":"Hunt hallucinated APIs, invented selectors, weak assertions."},{"label":"Verify (human)","detail":"Run against the real app; confirm it fails when the feature breaks."},{"label":"Own it (human)","detail":"Commit under your name means you read, verified and stand behind it."}]},"miniChallenge":"Take a test a teammate or an earlier you generated and merged, and run it back through the full loop as if reviewing it fresh. Note anything the original process missed — a weak assertion, an unverified locator, a missing plan. The gap between \"was merged\" and \"would survive the loop\" is a concrete measure of how much the workflow protects you."}$ench$::jsonb
